import re,io
def sents(path,a,b):
    L=io.open(path,encoding='utf-8').read().replace('\r','').split('\n')
    out={}
    for i in range(a-1,b):
        l=L[i]; m=re.search(r"ruling `\((R\d+)\)`\(([^)]*)\)(?:\(([^)]*)\))?",l)
        s=re.search(r"Supportable[^*]*?: \*(.+?)\*",l)
        if m and s: out[(m.group(1),m.group(2),m.group(3))]=(i+1,s.group(1))
    return out
R=sents('README.md',100,140); G=sents('REGISTRY.md',930,980)
for k in sorted(set(R)|set(G),key=lambda k:int(k[0][1:])):
    r=R.get(k);g=G.get(k)
    print(k, 'README :%s'%(r[0] if r else '-'), 'REGISTRY :%s'%(g[0] if g else '-'), 'EQUAL' if r and g and r[1]==g[1] else ('DIFF' if r and g else ''), (r or g)[1][:70])
